//! PostgreSQL adapter (outbound) for the `users` repository port.
//!
//! Generated by `hex-gen`. Queries are runtime-checked — the project
//! compiles without a database connection, and SQL problems surface as
//! [`RepositoryError`]s instead of build failures.

use async_trait::async_trait;
use chrono::{DateTime, Utc};
use uuid::Uuid;
use sqlx::PgPool;
use crate::domain::users::entity::Users;
use crate::domain::users::repository::UsersRepository;
use crate::enterprise::repository::{map_db_error, Page, Paginated, Repository, RepositoryError};
use crate::domain::users::enums::UserStatusEnum;

/// SQLx-backed adapter for the `users` table.
pub struct PostgresUsersRepository {
    pool: PgPool,
}

impl PostgresUsersRepository {
    /// Creates the adapter over a shared connection pool.
    pub fn new(pool: PgPool) -> Self {
        Self { pool }
    }
}

#[async_trait]
impl Repository<Users, Uuid> for PostgresUsersRepository {
    async fn find_by_id(&self, id: Uuid) -> Result<Option<Users>, RepositoryError> {
        sqlx::query_as::<_, Users>(
            "SELECT * FROM users WHERE id = $1",
        )
        .bind(id.clone())
        .fetch_optional(&self.pool)
        .await
        .map_err(map_db_error)
    }

    async fn find_all(&self, page: Page) -> Result<Paginated<Users>, RepositoryError> {
        let items = sqlx::query_as::<_, Users>(
            "SELECT * FROM users LIMIT $1 OFFSET $2",
        )
        .bind(page.limit())
        .bind(page.offset())
        .fetch_all(&self.pool)
        .await
        .map_err(map_db_error)?;
        let total = self.count().await?;
        Ok(Paginated { items, total, page: page.page, per_page: page.per_page })
    }

    async fn create(&self, entity: &Users) -> Result<Users, RepositoryError> {
        sqlx::query_as::<_, Users>(
            "INSERT INTO users (email, full_name, metadata, tags) VALUES ($1, $2, $3, $4) RETURNING *",
        )
        .bind(entity.email.clone()) // $1
        .bind(entity.full_name.clone()) // $2
        .bind(entity.metadata.clone()) // $3
        .bind(entity.tags.clone()) // $4
        .fetch_one(&self.pool)
        .await
        .map_err(map_db_error)
    }

    async fn update(&self, id: Uuid, entity: &Users) -> Result<Option<Users>, RepositoryError> {
        sqlx::query_as::<_, Users>(
            "UPDATE users SET email = $1, full_name = $2, user_status = $3, is_active = $4, metadata = $5, tags = $6, updated_at = now() WHERE id = $7 RETURNING *",
        )
        .bind(entity.email.clone()) // $1
        .bind(entity.full_name.clone()) // $2
        .bind(entity.user_status.clone()) // $3
        .bind(entity.is_active.clone()) // $4
        .bind(entity.metadata.clone()) // $5
        .bind(entity.tags.clone()) // $6
        .bind(id.clone()) // $7
        .fetch_optional(&self.pool)
        .await
        .map_err(map_db_error)
    }

    async fn delete(&self, id: Uuid) -> Result<bool, RepositoryError> {
        let result = sqlx::query(
            "DELETE FROM users WHERE id = $1",
        )
        .bind(id.clone())
        .execute(&self.pool)
        .await
        .map_err(map_db_error)?;
        Ok(result.rows_affected() > 0)
    }

    async fn count(&self) -> Result<i64, RepositoryError> {
        let (total,): (i64,) = sqlx::query_as(
            "SELECT COUNT(*) FROM users",
        )
        .fetch_one(&self.pool)
        .await
        .map_err(map_db_error)?;
        Ok(total)
    }
}

#[async_trait]
impl UsersRepository for PostgresUsersRepository {

    async fn find_by_status(&self, status: UserStatusEnum, page: Page) -> Result<Vec<Users>, RepositoryError> {
        sqlx::query_as::<_, Users>(
            "SELECT * FROM users WHERE user_status = $1 LIMIT $2 OFFSET $3",
        )
        .bind(status)
        .bind(page.limit())
        .bind(page.offset())
        .fetch_all(&self.pool)
        .await
        .map_err(map_db_error)
    }

    async fn set_status(&self, id: Uuid, status: UserStatusEnum) -> Result<Option<Users>, RepositoryError> {
        sqlx::query_as::<_, Users>(
            "UPDATE users SET user_status = $2, updated_at = now() WHERE id = $1 RETURNING *",
        )
        .bind(id.clone())
        .bind(status)
        .fetch_optional(&self.pool)
        .await
        .map_err(map_db_error)
    }

    async fn find_created_after(&self, ts: DateTime<Utc>, page: Page) -> Result<Vec<Users>, RepositoryError> {
        sqlx::query_as::<_, Users>(
            "SELECT * FROM users WHERE created_at >= $1 LIMIT $2 OFFSET $3",
        )
        .bind(ts)
        .bind(page.limit())
        .bind(page.offset())
        .fetch_all(&self.pool)
        .await
        .map_err(map_db_error)
    }

    async fn find_updated_after(&self, ts: DateTime<Utc>, page: Page) -> Result<Vec<Users>, RepositoryError> {
        sqlx::query_as::<_, Users>(
            "SELECT * FROM users WHERE updated_at >= $1 LIMIT $2 OFFSET $3",
        )
        .bind(ts)
        .bind(page.limit())
        .bind(page.offset())
        .fetch_all(&self.pool)
        .await
        .map_err(map_db_error)
    }
}
